        "summary": "この年は、日々の役割を見直しやすい時期でした。明るく走り続けてきたあなたを、周りの人がそっと支えてくれやすい年でした。現実を動かしてきた手を少し止め、この年は学びや準備に目が向きました。日々の過ごし方の中で、役割が変わることがあったかもしれません。人から支えられたり、気にかけてもらったりする場面が増えやすい年でした。この年は、人生の大きな流れが切り替わる節目でもありました。この年に支えてくれた人を思い出してみてください。",
