            "body": "この年は、人とのつながりに変化が生まれやすい時期でした。人生の時期としては、恋愛や結婚が身近な話題になりやすい年代でした。反応の早いあなたが、決まりや目上の人との関係の中で、言葉を選ぶことを覚える年でした。社会の中での立場がはっきりする年でした。少し距離を置いて、自分の気持ちを確かめることがあったかもしれません。知り合う人の輪が広がることもあったかもしれません。2月ごろからは、住まいや家族のことで責任を引き受ける約2年半の時期に入りました。この年、周りから信頼された出来事を思い出してみてください。",
