            "body": "この年の読み解きは、四柱推命（この年の干の意味、10年ごとの流れ、命式の各柱との関係）と、インド占星術（小さな周期の切り替わり、木星・土星の動き）を組み合わせています。\n\n四柱推命で、この年の干支が、あなたの命式のパートナーの座と強く響き合います。\n\n追い風・向かい風は、四柱推命で、生まれた日の干の強さと、この年の干支の五行との関係から見ています。\n\nあなた自身の性質は、生まれた日と月の干支から読んでいます。\n\n年齢や、交際・結婚の年数による一般的な傾向も合わせて見ています（著名人の記録では、結婚は27〜40歳、交際から結婚や別れまでは1〜4年目が約7割で2〜3年目が山、結婚から離婚までは約6年が中心）。\n\n前後の年とのつながりは、この時系列の判定を前の年・次の年と比べて示しています。\n\n対象期間：2023年の立春から翌年の立春まで（日本時間）。インド占星術の期間は実際の開始月・終了月で示しています。\n\n候補ラベルは、出来事を振り返り、考えるための目印です。当てはまる目印の数は、発生や確率を示しません。ラベルのない年にも、出会いや変化は起こり得ます。",
