        "title": "縁が育つ年",
        "summary": "この年は、人との関係が動きやすい時期でした。まっすぐ伸びたいあなたに枠や責任が求められ、我慢の中で幹が太くなる年でした。広げてきた活動に、決まりや責任が伴うようになる年でした。人と近づくきっかけが生まれることがあったかもしれません。大切な人との関わり方を見直すこともあったかもしれません。8月からは、人との縁や楽しみ、心地よい暮らしに目が向く時期に入りました。この年に向き合った大きな決断や課題は何でしたか。",
