            "text": "この年は、人との関係が動きやすい時期でした。まっすぐ伸びたいあなたに枠や責任が求められ、我慢の中で幹が太くなる年でした。広げてきた活動に、決まりや責任が伴うようになる年でした。人と近づくきっかけが生まれることがあったかもしれません。大切な人との関わり方を見直すこともあったかもしれません。8月からは、人との縁や楽しみ、心地よい暮らしに目が向く時期に入りました。この年に向き合った大きな決断や課題は何でしたか。"
          },
          {
            "role": "core",
            "label": "根拠と期間",
            "text": "この年の読み解きは、四柱推命（この年の干の意味、10年ごとの流れ、命式の各柱との関係）と、インド占星術（小さな周期の切り替わり、木星・土星の動き）を組み合わせています。\n\nインド占星術で、パートナーを表す金星の期間（2010年8月〜2013年8月）にあたります。\n\nインド占星術で、木星と土星がそろってパートナーの部屋に影響する年です。\n\n追い風・向かい風は、四柱推命で、生まれた日の干の強さと、この年の干支の五行との関係から見ています。\n\nあなた自身の性質は、生まれた日と月の干支から読んでいます。\n\n前後の年とのつながりは、この時系列の判定を前の年・次の年と比べて示しています。\n\n対象期間：2010年の立春から翌年の立春まで（日本時間）。インド占星術の期間は実際の開始月・終了月で示しています。\n\n候補ラベルは、出来事を振り返り、考えるための目印です。当てはまる目印の数は、発生や確率を示しません。ラベルのない年にも、出会いや変化は起こり得ます。"
          }
