        "summary": "この年は、人とのつながりが大きく変わりやすい時期でした。始まりと見直しが同時に起こりやすく、変化の幅が大きい流れでした。正しさを大切にするあなたが、組織のルールや役割と向き合い、立場がはっきりしていく年でした。暮らしを築いてきた歩みに、この年は責任ある立場や正式な約束が加わりました。知り合う人の輪が広がることがあったかもしれません。少し距離を置いて、自分の気持ちを確かめることもあったかもしれません。この年は、人生の大きな流れが切り替わる節目でもありました。この年に果たした役割や、守った約束は何でしたか。",
