        "summary": "この年は、身近な関係の形が変わりやすい時期でした。走り続けてきたあなたが、一度根を張り直し、学びや支えを取り込む年でした。忙しく動いてきた流れを一度ゆるめ、知識や支えを取り入れる年でした。人と近づくきっかけが生まれることがあったかもしれません。今ある関係が深まることもあったかもしれません。日々の過ごし方の中で、役割が変わることもあったかもしれません。6月ごろには、発信や身近な移動、学びの機会が増えやすい時期に入りました。この年に興味を持ったことや、学び始めたことは何でしたか。",
