            "text": "この年は、身近な関係の形が変わりやすい時期でした。走り続けてきたあなたが、一度根を張り直し、学びや支えを取り込む年でした。忙しく動いてきた流れを一度ゆるめ、知識や支えを取り入れる年でした。人と近づくきっかけが生まれることがあったかもしれません。今ある関係が深まることもあったかもしれません。日々の過ごし方の中で、役割が変わることもあったかもしれません。6月ごろには、発信や身近な移動、学びの機会が増えやすい時期に入りました。この年に興味を持ったことや、学び始めたことは何でしたか。"
          },
          {
            "role": "core",
            "label": "根拠と期間",
            "text": "この年の読み解きは、四柱推命（この年の干の意味、10年ごとの流れ、命式の各柱との関係）と、インド占星術（小さな周期の切り替わり、木星・土星の動き）を組み合わせています。\n\nインド占星術で、パートナーを表す金星の期間（2010年8月〜2013年8月）にあたります。\n\n四柱推命で、この年の干支が、あなたの命式のパートナーの座と強く響き合います。\n\nインド占星術で、木星と土星がそろってパートナーの部屋に影響する年です。\n\n仕事の転機の候補は、決めておいた目印が3つ当てはまる年に示しています。\n\n住まいの転機の候補は、決めておいた目印が2つ当てはまる年に示しています。\n\n追い風・向かい風は、四柱推命で、生まれた日の干の強さと、この年の干支の五行との関係から見ています。\n\nあなた自身の性質は、生まれた日と月の干支から読んでいます。\n\n前後の年とのつながりは、この時系列の判定を前の年・次の年と比べて示しています。\n\n対象期間：2012年の立春から翌年の立春まで（日本時間）。インド占星術の期間は実際の開始月・終了月で示しています。\n\n候補ラベルは、出来事を振り返り、考えるための目印です。当てはまる目印の数は、発生や確率を示しません。ラベルのない年にも、出会いや変化は起こり得ます。"
          }
