            "text": "無理なく続ける表現や楽しみ、暮らしの充実がテーマになる年でした。年齢の面では、関係の形を考える人が増えやすい年代にあたりました。長い目標を掲げるあなたが、その思いを言葉や形にして人に見せ始める年でした。現実的な積み重ねに、自分らしい工夫を加えられる年でした。現実を動かす行動力に新しいアイデアが加わり、仕事の幅が広がりやすくなりました。一緒に食事をしたり、趣味を楽しんだりする中で、自然に距離が縮まりやすい年でした。8月ごろには、パートナーや大切な相手との関係、約束ごとに光が当たりやすい時期に入りました。この年に楽しかったことや、続けていたことは何でしたか。"
          },
          {
            "role": "core",
            "label": "根拠と期間",
            "text": "この年の読み解きは、四柱推命（この年の干の意味、10年ごとの流れ、命式の各柱との関係）と、インド占星術（小さな周期の切り替わり、木星・土星の動き）を組み合わせています。\n\n追い風・向かい風は、四柱推命で、生まれた日の干の強さと、この年の干支の五行との関係から見ています。\n\nあなた自身の性質は、生まれた日と月の干支から読んでいます。\n\n年齢や、交際・結婚の年数による一般的な傾向も合わせて見ています（著名人の記録では、結婚は27〜40歳、交際から結婚や別れまでは1〜4年目が約7割で2〜3年目が山、結婚から離婚までは約6年が中心）。\n\n前後の年とのつながりは、この時系列の判定を前の年・次の年と比べて示しています。\n\n対象期間：2016年の立春から翌年の立春まで（日本時間）。インド占星術の期間は実際の開始月・終了月で示しています。\n\n候補ラベルは、出来事を振り返り、考えるための目印です。当てはまる目印の数は、発生や確率を示しません。ラベルのない年にも、出会いや変化は起こり得ます。"
