        "title": "世界を広げる年",
        "summary": "新しい交流や人のつながり、時間とお金の使い方がテーマになる年でした。開拓者気質のあなたが行動範囲を広げ、手にしたものをどう使うかを考える年でした。成果を求める流れが重なる年でした。現実的な持ち味が前面に出て成果を出しやすい一方、忙しさで疲れをためやすくなりました。人との出会いや交流の機会が増え、付き合いの幅が広がりやすい年でした。10月ごろには、遠くへの旅や学び直しで、考え方が広がりやすい時期に入りました。この年に広がったつながりの中で、今も続いているものはありますか。",
