            "text": "新しい交流や人のつながり、時間とお金の使い方がテーマになる年でした。開拓者気質のあなたが行動範囲を広げ、手にしたものをどう使うかを考える年でした。成果を求める流れが重なる年でした。現実的な持ち味が前面に出て成果を出しやすい一方、忙しさで疲れをためやすくなりました。人との出会いや交流の機会が増え、付き合いの幅が広がりやすい年でした。10月ごろには、遠くへの旅や学び直しで、考え方が広がりやすい時期に入りました。この年に広がったつながりの中で、今も続いているものはありますか。"
          },
          {
            "role": "core",
            "label": "根拠と期間",
            "text": "この年の読み解きは、四柱推命（この年の干の意味、10年ごとの流れ、命式の各柱との関係）と、インド占星術（小さな周期の切り替わり、木星・土星の動き）を組み合わせています。\n\n追い風・向かい風は、四柱推命で、生まれた日の干の強さと、この年の干支の五行との関係から見ています。\n\nあなた自身の性質は、生まれた日と月の干支から読んでいます。\n\n前後の年とのつながりは、この時系列の判定を前の年・次の年と比べて示しています。\n\n対象期間：2018年の立春から翌年の立春まで（日本時間）。インド占星術の期間は実際の開始月・終了月で示しています。\n\n候補ラベルは、出来事を振り返り、考えるための目印です。当てはまる目印の数は、発生や確率を示しません。ラベルのない年にも、出会いや変化は起こり得ます。"
          }
