        "summary": "この年は、身近な関係の形が変わりやすい時期でした。年齢の流れから見ると、人との縁を形にするかどうかを考える人が多い頃でした。まっすぐ伸びたいあなたに枠や責任が求められ、我慢の中で幹が太くなる年でした。広げてきた活動に、決まりや責任が伴うようになる年でした。少し距離を置いて、自分の気持ちを確かめることがあったかもしれません。人と近づくきっかけが生まれることもあったかもしれません。仕事では、扱う商品やサービスを見直すこともあったかもしれません。この年は、人生の大きな流れが切り替わる節目でもありました。この年、周りから信頼された出来事を思い出してみてください。",
