        "title": "仕事が変わる年",
        "summary": "この年は、仕事や役割の形が変わりやすい時期でした。目標に向かうあなたを、目上の人や学びの場が後押ししてくれやすい年でした。責任を担う日々に、この年は学びや支えが力として加わりました。仕事では、扱う分野や取引先が変わることがあったかもしれません。価値観の近い人や、知的な刺激をくれる人との会話が増えやすい年でした。4月ごろには、自分自身に追い風が向き、新しいことを始めやすい時期に入りました。この年、進む方向を変えたことはありましたか。",
        "tags": [
          "時期",
