        "id": "turning-year-2024",
        "kind": "timing",
        "tab": "timing",
        "scope": "self",
        "title": "関係を見直す年",
        "summary": "この年は、身近な関係の形が変わりやすい時期でした。人生の時期としては、恋愛や結婚が身近な話題になりやすい年代でした。人を巻き込んで道を切り開くあなたが、誰と組み、どこを一人で進むかを選び直す年でした。責任を担う日々の中で、この年は自分の意思をはっきりさせたくなりました。続けるか区切るかを考える関係が出てくることがあったかもしれません。今ある関係が深まることもあったかもしれません。5月ごろには、発信や身近な移動、学びの機会が増えやすい時期に入りました。この年、譲れなかったことは何でしたか。それは今も大切ですか。",
        "tags": [
