        "summary": "この年は、人との関係が動きやすい時期でした。まっすぐ目標に向かうあなたには、同じ志を持つ仲間が現れ、自分の旗を立て直す年でした。役割や決まりを守りながら、自分らしさを取り戻していく年でした。知り合う人の輪が広がることがあったかもしれません。今ある関係が深まることもあったかもしれません。4月ごろからは、自分のあり方を問い直し、地に足をつける約2年半の時期に入りました。この年に力を合わせた人や、競い合った人を思い出してみてください。",
